// reasoningRequestOptions builds per-request options. For thinking models
// (Qwen3, DeepSeek-R1 etc.) apply provider-specific non-standard body fields
// only when the concrete provider declares the matching wire support.
func (p *Provider) reasoningRequestOptions(model string, opts agent.Options) ([]option.RequestOption, reasoningpolicy.Reasoning, error) {
	policy, err := reasoningpolicy.Parse(opts.Reasoning)
	if err != nil {
		return nil, "", err
	}
	explicitRequest := policy.IsSet()
	if !explicitRequest {
		policy, err = reasoningpolicy.Parse(p.reasoningDefault)
		if err != nil {
			return nil, "", err
		}
	}

	if !policy.IsSet() || policy.Kind == reasoningpolicy.KindAuto {
		return nil, "", nil
	}

	// Catalog reasoning_wire metadata gates the wire shape before any
	// provider-specific encoding runs. Models flagged as reasoning_wire=none
	// have no reasoning surface at all; an explicit non-off request is a
	// catalog/wire mismatch and must surface as an error rather than be
	// silently dropped. Models flagged as reasoning_wire=model_id encode the
	// reasoning level in the model name (e.g. fixed-variant Qwen3.6) and the
	// upstream endpoint cannot honor an external reasoning toggle, so the
	// reasoning field must be stripped from the wire body.
	catalogWire := p.modelReasoningWireFor(model)
	switch catalogWire {
	case "none":
		if explicitRequest && !policy.IsExplicitOff() {
			return nil, "", fmt.Errorf("openai: model %q has reasoning_wire=none; explicit reasoning=%q is not supported", model, policy.Value)
		}
		return nil, "", nil
	case "model_id":
		return nil, "", nil
	}

	if !p.SupportsThinking() {
		if policy.IsExplicitOff() {
			return nil, reasoningpolicy.ReasoningOff, nil
		}
		if explicitRequest {
			return nil, "", fmt.Errorf("openai: reasoning=%q is not supported by provider type %q", policy.Value, p.providerSystem)
		}
		return nil, "", nil
	}

	if policy.IsExplicitOff() {
		switch p.thinkingWireFormat() {
		case ThinkingWireFormatQwen:
			if !isQwenModel(model) {
				if explicitRequest && p.strictThinkingModelMatch() {
					return nil, "", fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
				}
				return nil, "", nil
			}
			return []option.RequestOption{
				option.WithJSONSet("chat_template_kwargs", map[string]interface{}{
					"enable_thinking": false,
				}),
			}, reasoningpolicy.ReasoningOff, nil
		case ThinkingWireFormatOpenRouter:
			return []option.RequestOption{option.WithJSONSet("reasoning", map[string]interface{}{
				"effort": "none",
			})}, reasoningpolicy.ReasoningOff, nil
		case ThinkingWireFormatOpenAIEffort:
			return []option.RequestOption{option.WithJSONSet("think", false)}, reasoningpolicy.ReasoningOff, nil
		}
		return nil, reasoningpolicy.ReasoningOff, nil
	}

	if p.thinkingWireFormat() == ThinkingWireFormatOpenRouter {
		return openRouterReasoningOptions(policy, model, catalogWire)
	}
	if p.thinkingWireFormat() == ThinkingWireFormatOpenAIEffort {
		return openAIEffortReasoningOptions(policy, p.protocolCapabilities().ReasoningAliasMap, p.logger, model, p.providerSystem)
	}
	if p.thinkingWireFormat() == ThinkingWireFormatQwen && !isQwenModel(model) {
		if explicitRequest && p.strictThinkingModelMatch() {
			return nil, "", fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
		}
		return nil, "", nil
	}

	// Qwen and ThinkingMap providers can only express a token budget on the
	// wire. If the catalog declares effort wire for this model, degrade
	// gracefully: snap KindTokens to the nearest PortableBudgets tier so the
	// downstream budget calculation uses a standard value. The model still
	// works; the catalog entry is simply mis-classified.
	if catalogWire == "effort" {
		p.logger.Warn("catalog declares effort wire but provider only supports budget wire",
			"model", model,
			"provider", p.providerSystem,
		)
		if policy.Kind == reasoningpolicy.KindTokens {
			tier := reasoningpolicy.NearestTierForTokens(policy.Tokens)
			policy = reasoningpolicy.Policy{Kind: reasoningpolicy.KindNamed, Value: tier}
		}
	}

	thinkingBudget, err := reasoningpolicy.BudgetFor(policy, nil, 0)
	if err != nil {
		return nil, "", fmt.Errorf("openai: %w", err)
	}
	if thinkingBudget <= 0 {
		return nil, "", nil
	}
	emitted := reasoningpolicy.ReasoningTokens(thinkingBudget)

	switch p.thinkingWireFormat() {
	case ThinkingWireFormatQwen:
		return []option.RequestOption{
			option.WithJSONSet("chat_template_kwargs", map[string]interface{}{
				"enable_thinking": true,
				"thinking_budget": thinkingBudget,
			}),
		}, emitted, nil
	case "", ThinkingWireFormatThinkingMap:
		return []option.RequestOption{option.WithJSONSet("thinking", map[string]interface{}{
			"type":          "enabled",
			"budget_tokens": thinkingBudget,
		})}, emitted, nil
	default:
		return nil, "", fmt.Errorf("openai: unsupported thinking wire format %q for provider type %q", p.thinkingWireFormat(), p.providerSystem)
	}
}

// openAIEffortReasoningOptions builds the flat top-level reasoning_effort wire
// used by ds4 / deepseek-v4-flash. Named tiers are emitted as-is; token
// budgets are snapped to the nearest PortableBudgets tier via NearestTierForTokens.
// Alias maps from live introspection are applied after snapping so ds4's
// low/medium/xhigh→high aliasing is reflected on the wire.
func openAIEffortReasoningOptions(policy reasoningpolicy.Policy, aliasMap map[string]string, logger *slog.Logger, model, providerSystem string) ([]option.RequestOption, reasoningpolicy.Reasoning, error) {
	var tier reasoningpolicy.Reasoning
	switch policy.Kind {
	case reasoningpolicy.KindTokens:
		tier = reasoningpolicy.NearestTierForTokens(policy.Tokens)
	case reasoningpolicy.KindNamed:
		tier = policy.Value
	default:
		return nil, "", fmt.Errorf("openai: unsupported OpenAI effort reasoning policy kind %q", policy.Kind)
	}
	normalized, changed := applyReasoningAliasMap(reasoningpolicy.Policy{Kind: reasoningpolicy.KindNamed, Value: tier}, aliasMap)
	if changed && logger != nil {
		logger.Warn("reasoning alias map overrode requested tier",
			"model", model,
			"provider", providerSystem,
			"reasoning_intent", string(tier),
			"reasoning_emitted", string(normalized.Value),
			"reasoning_emitted_reason", providerSystem+" alias map",
		)

	assert.Empty(t, logHandler.Messages(), "wire=tokens on Qwen must not emit a warning")
}

// captureOpenAIChatBodyWithOpenAIEffort constructs an OpenAIEffort-format provider
// (ThinkingWireFormatOpenAIEffort) and returns the captured request body.
func captureOpenAIChatBodyWithOpenAIEffort(t *testing.T, model string, logger *slog.Logger, opts agent.Options) ([]byte, error) {
	t.Helper()
	var capturedBody []byte
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		capturedBody = body
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{
			"id":"chatcmpl-1",
			"model":"` + model + `",
			"choices":[{"index":0,"message":{"role":"assistant","content":"done"},"finish_reason":"stop"}],
			"usage":{"prompt_tokens":12,"completion_tokens":5,"total_tokens":17}
		}`))
	}))
	defer srv.Close()

	caps := openai.OpenAIProtocolCapabilities
	caps.Thinking = true
	caps.ThinkingFormat = openai.ThinkingWireFormatOpenAIEffort
	caps.ReasoningAliasMap = map[string]string{
		"low":    "high",
		"medium": "high",
		"xhigh":  "high",
	}
	caps.SupportedRequestParams = []string{"reasoning_effort", "think"}

	p := openai.New(openai.Config{
		BaseURL:        srv.URL + "/v1",
		APIKey:         "test",
		Model:          model,
		ProviderSystem: "ds4",
		Capabilities:   &caps,
		Logger:         logger,
	})
	_, err := p.Chat(context.Background(), []agent.Message{{Role: agent.RoleUser, Content: "hello"}}, nil, opts)
	return capturedBody, err
}

// TestQwenReasoningWireChatTemplateKwargsEnvelope verifies that the Qwen wire format
// emits enable_thinking and thinking_budget inside a chat_template_kwargs envelope,
// not at the top level. This is the sindri llama-server fix from the 2026-05-11 probe:
// top-level enable_thinking/thinking_budget are silently dropped by llama-server,
// but the chat_template_kwargs envelope activates thinking (250-526 completion tokens
// with extracted reasoning_content).
func TestQwenReasoningWireChatTemplateKwargsEnvelope(t *testing.T) {
	const model = "Qwen3.6-27B-UD-Q3_K_XL.gguf"

	t.Run("on/emits chat_template_kwargs envelope", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithReasoningWireQwen(t, model, nil, nil, agent.Options{Reasoning: agent.ReasoningTokens(4096)})
		require.NoError(t, err)
		assertQwenReasoningWireBudget(t, body, true, 4096)
	})

	t.Run("off/emits chat_template_kwargs.enable_thinking=false", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithReasoningWireQwen(t, model, nil, nil, agent.Options{Reasoning: agent.ReasoningOff})
		require.NoError(t, err)
		assertQwenReasoningWireBudget(t, body, false, 0)
	})
}

// TestOpenAIEffortReasoningWire verifies the flat top-level reasoning_effort wire
// emitted by OpenAIEffort-format providers (ds4 / deepseek-v4-flash).
func TestOpenAIEffortReasoningWire(t *testing.T) {
	const model = "deepseek-v4-flash"

	t.Run("high/emits reasoning_effort:high", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithOpenAIEffort(t, model, nil, agent.Options{Reasoning: agent.ReasoningHigh})
		require.NoError(t, err)
		assertOpenAIEffortReasoningWire(t, body, "high")
	})

	t.Run("low/emits reasoning_effort:high via alias map", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithOpenAIEffort(t, model, nil, agent.Options{Reasoning: agent.ReasoningLow})
		require.NoError(t, err)
		assertOpenAIEffortReasoningWire(t, body, "high")
	})

	t.Run("off/emits think:false", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithOpenAIEffort(t, model, nil, agent.Options{Reasoning: agent.ReasoningOff})
		require.NoError(t, err)
		assertOpenAIEffortOffWire(t, body)
	})

	t.Run("tokens=4096/snaps to high via alias map", func(t *testing.T) {
		body, err := captureOpenAIChatBodyWithOpenAIEffort(t, model, nil, agent.Options{Reasoning: agent.ReasoningTokens(4096)})
		require.NoError(t, err)
		assertOpenAIEffortReasoningWire(t, body, "high")
	})
}

func TestOpenAIEffortReasoningWireAliasMapWarning(t *testing.T) {
	const model = "deepseek-v4-flash"
	logHandler := &testLogHandler{}
	logger := slog.New(logHandler)

	body, err := captureOpenAIChatBodyWithOpenAIEffort(t, model, logger, agent.Options{Reasoning: agent.ReasoningLow})
	require.NoError(t, err)
	assertOpenAIEffortReasoningWire(t, body, "high")

	msgs := logHandler.Messages()
	require.NotEmpty(t, msgs, "expected a structured warning log for ds4 alias map")
	assert.Contains(t, msgs[0], "reasoning alias map overrode requested tier")
	assert.True(t, logHandler.HasAttr("reasoning_emitted_reason", "ds4 alias map"))
	assert.True(t, logHandler.HasAttr("reasoning_emitted", "high"))
}

func TestOpenAIEffortReasoningWireEmittedTelemetry(t *testing.T) {
	const model = "deepseek-v4-flash"
	var bodyMu sync.Mutex
	var capturedBody []byte
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		bodyMu.Lock()
		capturedBody = append([]byte(nil), body...)
		bodyMu.Unlock()
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{
			"id":"chatcmpl-1",
			"model":"` + model + `",
			"choices":[{"index":0,"message":{"role":"assistant","content":"done"},"finish_reason":"stop"}],
			"usage":{"prompt_tokens":12,"completion_tokens":5,"total_tokens":17}
		}`))
	}))
	defer srv.Close()

	caps := openai.OpenAIProtocolCapabilities
	caps.Thinking = true
	caps.ThinkingFormat = openai.ThinkingWireFormatOpenAIEffort
	caps.ReasoningAliasMap = map[string]string{
		"low":    "high",
		"medium": "high",
		"xhigh":  "high",
	}
	caps.SupportedRequestParams = []string{"reasoning_effort", "think"}

	p := openai.New(openai.Config{
		BaseURL:        srv.URL + "/v1",
		APIKey:         "test",
		Model:          model,
		ProviderSystem: "ds4",
		Capabilities:   &caps,
	})

	resp, err := p.Chat(context.Background(), []agent.Message{{Role: agent.RoleUser, Content: "hello"}}, nil, agent.Options{Reasoning: agent.ReasoningLow})
	require.NoError(t, err)
	bodyMu.Lock()
	defer bodyMu.Unlock()
	assert.Contains(t, string(capturedBody), `"reasoning_effort":"high"`)
	require.NotNil(t, resp.Attempt)
	assert.Equal(t, string(agent.ReasoningHigh), resp.Attempt.ReasoningEmitted)
}

