	t.Helper()

	var capturedBody []byte
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch {
		case r.Method == http.MethodGet && r.URL.Path == "/props":
			w.Header().Set("Content-Type", "application/json")
			_, _ = w.Write([]byte(`{
				"chat_template":"{{ enable_thinking }}",
				"default_generation_settings":{"params":{"reasoning_format":"deepseek"}}
			}`))
		case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/chat/completions"):
			body, _ := io.ReadAll(r.Body)
			capturedBody = append([]byte(nil), body...)
			w.Header().Set("Content-Type", "application/json")
			_, _ = w.Write([]byte(`{
				"id":"chatcmpl-1",
				"model":"` + llamaserverThinkingTestModel + `",
				"choices":[{"index":0,"message":{"role":"assistant","content":"done"},"finish_reason":"stop"}],
				"usage":{"prompt_tokens":12,"completion_tokens":5,"total_tokens":17}
			}`))
		default:
			http.NotFound(w, r)
		}
	}))
	t.Cleanup(srv.Close)

	p := llamaserver.New(llamaserver.Config{
		BaseURL: srv.URL + "/v1",
		APIKey:  "test",
		Model:   llamaserverThinkingTestModel,
	})

	_, err := p.Chat(context.Background(), []agent.Message{{Role: agent.RoleUser, Content: "hello"}}, nil, agent.Options{
		Reasoning: reasoning,
	})
	require.NoError(t, err)
	require.NotNil(t, capturedBody)
	return capturedBody
