func assertLlamaserverThinkingWire(t *testing.T, body []byte, wantEnabled bool) {
	t.Helper()

	var reqBody map[string]interface{}
	require.NoError(t, json.Unmarshal(body, &reqBody))

	assert.NotContains(t, reqBody, "enable_thinking", "llama-server Qwen controls must use chat_template_kwargs: %s", string(body))
	assert.NotContains(t, reqBody, "thinking_budget", "llama-server Qwen controls must stay nested: %s", string(body))

	ctk, ok := reqBody["chat_template_kwargs"].(map[string]interface{})
	require.True(t, ok, "request body must include chat_template_kwargs: %s", string(body))

	assert.Equal(t, wantEnabled, ctk["enable_thinking"])
	if wantEnabled {
